<?php
session_start();
require_once 'conexion.php';
require_once 'auth.php';
asegurarSistemaUsuarios($conexion);
exigirRoles(array('ADMINISTRADOR'));
if (strtoupper((string)($_SERVER['REQUEST_METHOD'] ?? 'GET')) === 'POST') {
    automacValidarCsrf(true);
}
function e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$mensaje='';$tipo='ok';
if($_SERVER['REQUEST_METHOD']==='POST'){
    try{
        $accion=(string)($_POST['accion']??'');
        if($accion==='guardar'){
            $id=(int)($_POST['usuario_id']??0);$login=strtolower(trim((string)($_POST['usuario_login']??'')));$nombre=trim((string)($_POST['usuario_nombre']??''));$rol=(string)($_POST['usuario_rol']??'');$activo=(string)($_POST['usuario_activo']??'SI');$clave=(string)($_POST['clave']??'');
            if(!preg_match('/^[a-z0-9._-]{3,50}$/',$login))throw new RuntimeException('El usuario debe tener entre 3 y 50 caracteres y usar letras, números, punto, guion o guion bajo.');
            if($nombre==='')throw new RuntimeException('Debe ingresar el nombre.');
            if(!in_array($rol,array('ADMINISTRADOR','COMERCIAL','TECNICO'),true))throw new RuntimeException('Rol inválido.');
            if(!in_array($activo,array('SI','NO'),true))$activo='SI';
            if($id===0){if(strlen($clave)<4)throw new RuntimeException('La contraseña temporal debe tener al menos 4 caracteres.');$hash=password_hash($clave,PASSWORD_DEFAULT);$st=$conexion->prepare("INSERT INTO usuarios(usuario_login,usuario_nombre,usuario_password,usuario_rol,usuario_activo,usuario_debe_cambiar_clave) VALUES(?,?,?,?,?,'SI')");$st->bind_param('sssss',$login,$nombre,$hash,$rol,$activo);$st->execute();$st->close();$mensaje='Usuario creado correctamente.';}
            else{$st=$conexion->prepare('UPDATE usuarios SET usuario_login=?,usuario_nombre=?,usuario_rol=?,usuario_activo=?,usuario_modificado=NOW() WHERE usuario_id=?');$st->bind_param('ssssi',$login,$nombre,$rol,$activo,$id);$st->execute();$st->close();$mensaje='Usuario actualizado correctamente.';}
        }elseif($accion==='restablecer'){
            $id=(int)($_POST['usuario_id']??0);$clave=(string)($_POST['clave_nueva']??'');if(strlen($clave)<4)throw new RuntimeException('La contraseña temporal debe tener al menos 4 caracteres.');$hash=password_hash($clave,PASSWORD_DEFAULT);$st=$conexion->prepare("UPDATE usuarios SET usuario_password=?,usuario_debe_cambiar_clave='SI',usuario_modificado=NOW() WHERE usuario_id=?");$st->bind_param('si',$hash,$id);$st->execute();$st->close();$mensaje='Contraseña temporal restablecida.';
        }
    }catch(Throwable $ex){$mensaje=$ex->getMessage();$tipo='error';}
}
$editar=null;$eid=filter_input(INPUT_GET,'editar',FILTER_VALIDATE_INT);if($eid){$st=$conexion->prepare('SELECT * FROM usuarios WHERE usuario_id=?');$st->bind_param('i',$eid);$st->execute();$editar=$st->get_result()->fetch_assoc();$st->close();}
$usuarios=$conexion->query('SELECT * FROM usuarios ORDER BY usuario_nombre,usuario_login');
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Usuarios</title><style>*{box-sizing:border-box}body{font-family:Arial;background:#f4f4f9;margin:18px;color:#202124}.c{max-width:1150px;margin:auto}.menu{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:14px}.menu a,.btn,button{padding:9px 12px;border:0;border-radius:5px;background:#343a40;color:#fff;text-decoration:none;font-weight:bold;font-size:12px;cursor:pointer}.menu .activo,.azul{background:#0d6efd}.verde{background:#198754}.rojo{background:#dc3545}.gris{background:#6c757d}.caja{background:#fff;border:1px solid #ddd;border-radius:8px;padding:18px;margin-bottom:15px}.form{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}label{display:block;font-size:12px;font-weight:bold;margin-bottom:4px}input,select{width:100%;height:35px;padding:5px}.acciones{grid-column:1/-1}.msg{padding:10px;border-radius:5px;margin-bottom:12px}.ok{background:#d1e7dd;color:#0f5132}.error{background:#f8d7da;color:#842029}table{width:100%;border-collapse:collapse;font-size:13px}th,td{padding:8px;border-bottom:1px solid #ddd;text-align:left}th{background:#212529;color:#fff}.rest{display:flex;gap:5px}.rest input{width:135px;height:31px}@media(max-width:750px){.form{grid-template-columns:1fr}.tabla{overflow:auto}}</style></head><body><div class="c"><?php require __DIR__ . '/menu.php'; ?><h1>Administración de usuarios</h1><?php if($mensaje):?><div class="msg <?=$tipo?>"><?=e($mensaje)?></div><?php endif;?><section class="caja"><h2><?=$editar?'Modificar usuario':'Nuevo usuario'?></h2><form method="post" class="form"><?= automacCsrfInput() ?><input type="hidden" name="accion" value="guardar"><input type="hidden" name="usuario_id" value="<?= (int)($editar['usuario_id']??0) ?>"><div><label>Usuario</label><input name="usuario_login" required value="<?=e($editar['usuario_login']??'')?>"></div><div><label>Nombre</label><input name="usuario_nombre" required value="<?=e($editar['usuario_nombre']??'')?>"></div><div><label>Rol</label><select name="usuario_rol"><option value="ADMINISTRADOR"<?=($editar['usuario_rol']??'')==='ADMINISTRADOR'?' selected':''?>>Administrador</option><option value="COMERCIAL"<?=($editar['usuario_rol']??'')==='COMERCIAL'?' selected':''?>>Comercial</option><option value="TECNICO"<?=($editar['usuario_rol']??'')==='TECNICO'?' selected':''?>>Técnico</option></select></div><div><label>Estado</label><select name="usuario_activo"><option value="SI"<?=($editar['usuario_activo']??'SI')==='SI'?' selected':''?>>Activo</option><option value="NO"<?=($editar['usuario_activo']??'')==='NO'?' selected':''?>>Desactivado</option></select></div><?php if(!$editar):?><div><label>Contraseña temporal</label><input type="password" name="clave" required></div><?php endif;?><div class="acciones"><button class="azul">GUARDAR</button> <?php if($editar):?><a class="btn gris" href="administrar_usuarios.php">CANCELAR</a><?php endif;?></div></form></section><section class="caja tabla"><table><tr><th>Usuario</th><th>Nombre</th><th>Rol</th><th>Estado</th><th>Último acceso</th><th>Acciones</th></tr><?php while($u=$usuarios->fetch_assoc()):?><tr><td><?=e($u['usuario_login'])?></td><td><?=e($u['usuario_nombre'])?></td><td><?=e($u['usuario_rol'])?></td><td><?=e($u['usuario_activo'])?></td><td><?=e($u['usuario_ultimo_acceso']?:'—')?></td><td><a class="btn azul" href="?editar=<?=(int)$u['usuario_id']?>">MODIFICAR</a><form method="post" class="rest" style="display:inline-flex"><?= automacCsrfInput() ?><input type="hidden" name="accion" value="restablecer"><input type="hidden" name="usuario_id" value="<?=(int)$u['usuario_id']?>"><input type="password" name="clave_nueva" placeholder="Clave temporal" required><button class="gris">RESTABLECER</button></form></td></tr><?php endwhile;?></table></section></div></body></html>
